    &self,
    haystack: &[u8],
    caps: &mut Self::Captures,
    dst: &mut Vec<u8>,
    append: F,
) -> Result<(), Self::Error>
where
    F: FnMut(&Self::Captures, &mut Vec<u8>) -> bool,
{
    self.replace_with_captures_at(haystack, 0, caps, dst, append)
}

