./tests/misc.rs:1143:// The following series of tests seeks to test all permutations of ripgrep's
./tests/misc.rs:1144:// sorted queries.
./tests/misc.rs:1145://
./tests/misc.rs:1146:// They all rely on this setup function, which sets up this particular file
./tests/misc.rs:1147:// structure with a particular creation order:
./tests/misc.rs:1148://  ├── a             # 1
./tests/misc.rs:1149://  ├── b             # 4
./tests/misc.rs:1150://  └── dir           # 2
./tests/misc.rs:1151://     ├── c          # 3
./tests/misc.rs:1152://     └── d          # 5
./tests/misc.rs:1153://
./tests/misc.rs:1154:// This order is important when sorting them by system time-stamps.
./tests/misc.rs:1155:fn sort_setup(dir: Dir) {
./tests/misc.rs:1156:    use std::{thread::sleep, time::Duration};
./tests/misc.rs:1157:    // As reported in https://github.com/BurntSushi/ripgrep/issues/3071
./tests/misc.rs:1158:    // this test fails if sufficient delay is not given on Windows/Aarch64.
./tests/misc.rs:1159:    let delay = if cfg!(all(windows, target_arch = "aarch64")) {
./tests/misc.rs:1160:        Duration::from_millis(1000)
./tests/misc.rs:1161:    } else {
./tests/misc.rs:1162:        Duration::from_millis(100)
./tests/misc.rs:1163:    };
./tests/misc.rs:1164:    let sub_dir = dir.path().join("dir");
./tests/misc.rs:1165:    dir.create("a", "test");
./tests/misc.rs:1166:    sleep(delay);
./tests/misc.rs:1167:    dir.create_dir(&sub_dir);
./tests/misc.rs:1168:    sleep(delay);
./tests/misc.rs:1169:    dir.create(sub_dir.join("c"), "test");
./tests/misc.rs:1170:    sleep(delay);
./tests/misc.rs:1171:    dir.create("b", "test");
./tests/misc.rs:1172:    sleep(delay);
./tests/misc.rs:1173:    dir.create(sub_dir.join("d"), "test");
./tests/misc.rs:1174:}
