/**
 * Utilities for handling HTTP redirects with validation
 */

import type { AstroConfig } from '../../types/public/config.js';
import { isRemoteAllowed } from '@astrojs/internal-helpers/remote';

export type RemoteImageConfig = Pick<AstroConfig['image'], 'remotePatterns' | 'domains'>;

export type FetchRedirectOptions = {
	/**
	 * URL to fetch (either string or URL object)
	 */
	url: string | URL;

	/**
	 * Headers to include in the request (optional)
	 */
	headers?: Headers;

	/**
	 * Image config for validating redirect destinations (optional)
	 */
	imageConfig: RemoteImageConfig;

	/**
	 * Fetch function to use (default: globalThis.fetch)
	 */
	fetchFn?: typeof fetch;

	/**
	 * Maximum number of redirects to follow (default: 10)
	 */
	redirectLimit?: number;

	/**
	 * Error handler for redirect depth exceeded (default: generic Error)
	 */
	onMaxRedirectsExceeded?: (url: string) => Error;

	/**
	 * Error handler for missing Location header (default: generic Error)
	 */
	onMissingLocationHeader?: (status: number, url: string) => Error;

	/**
	 * Error handler for disallowed redirect (default: generic Error)
	 */
	onDisallowedRedirect?: (currentUrl: string, targetUrl: string) => Error;
};

/**
 * Recursively follows HTTP redirects with validation according to the image configuration.
 *
 * If any of the domains in the redirect chain are not allowed by either `image.remotePatterns`
 * or `image.domains`, this function will throw an error for a disallowed redirect.
 *
 * @param options The options for this fetch call.
 */
export async function fetchWithRedirects(options: FetchRedirectOptions): Promise<Response> {
	const {
		url,
		headers,
		imageConfig,
		fetchFn = globalThis.fetch,
		redirectLimit = 10,
		onMaxRedirectsExceeded = (_u) => new Error('Maximum redirect depth exceeded'),
		onMissingLocationHeader = (_s, _u) =>
			new Error(`Redirect response ${_s} missing Location header`),
		onDisallowedRedirect = (_current, _target) =>
			new Error(
				`The image at ${_current} redirected to ${_target}, which is not an allowed remote location.`,
			),
	} = options;

	if (redirectLimit <= 0) {
		throw onMaxRedirectsExceeded(typeof url === 'string' ? url : url.toString());
	}

	const urlString = typeof url === 'string' ? url : url.toString();
	const req = new Request(url, { headers });
	const res = await fetchFn(req, { redirect: 'manual' });

	// Handle redirects (301, 302, 303, 307, 308 are actual redirects, not 304 Not Modified)
	if ([301, 302, 303, 307, 308].includes(res.status)) {
		const location = res.headers.get('Location');
		if (!location) {
			throw onMissingLocationHeader(res.status, urlString);
		}

		// Resolve the redirect URL relative to the current URL
		const redirectUrl = new URL(location, urlString).toString();

		// Validate that the redirect target matches allowed patterns
		if (
			!isRemoteAllowed(redirectUrl, {
				domains: imageConfig.domains ?? [],
				remotePatterns: imageConfig.remotePatterns ?? [],
			})
		) {
			throw onDisallowedRedirect(urlString, redirectUrl);
		}

		// Recursively follow the redirect
		return fetchWithRedirects({
			url: redirectUrl,
			headers,
			imageConfig,
			fetchFn,
			redirectLimit: redirectLimit - 1,
			onMaxRedirectsExceeded,
			onMissingLocationHeader,
			onDisallowedRedirect,
		});
	}

	return res;
}

	if (isImageMetadata(options)) {
		throw new AstroError(AstroErrorData.ExpectedNotESMImage);
	}

	const service = await getConfiguredImageService();

	// If the user inlined an import, something fairly common especially in MDX, or passed a function that returns an Image, await it for them
	const resolvedOptions: ImageTransform = {
		...options,
		src: await resolveSrc(options.src),
	};

	let originalWidth: number | undefined;
	let originalHeight: number | undefined;

	// Infer size for remote images if inferSize is true
	if (resolvedOptions.inferSize) {
		delete resolvedOptions.inferSize; // Delete so it doesn't end up in the attributes

		if (isRemoteImage(resolvedOptions.src) && isRemotePath(resolvedOptions.src)) {
			if (!isRemoteAllowed(resolvedOptions.src, imageConfig)) {
				throw new AstroError({
					...AstroErrorData.RemoteImageNotAllowed,
					message: AstroErrorData.RemoteImageNotAllowed.message(resolvedOptions.src),
				});
			}

			const getRemoteSize = (url: string) =>
				service.getRemoteSize?.(url, imageConfig, logger) ?? inferRemoteSize(url, imageConfig);
			const result = await getRemoteSize(resolvedOptions.src); // Directly probe the image URL
			resolvedOptions.width ??= result.width;
			resolvedOptions.height ??= result.height;
			// We've already paid for the fetch; reuse it to pin down the output format so the URL
			// (and any baked filename) doesn't have to defer or refetch.
			if (result.format) {
				resolvedOptions.format ??= resolveDefaultOutputFormat(result.format);
			}
			originalWidth = result.width;
			originalHeight = result.height;
		}
	}

	const originalFilePath = isESMImportedImage(resolvedOptions.src)
		? resolvedOptions.src.fsPath
		: undefined; // Only set for ESM imports, where we do have a file path

	// Clone the `src` object if it's an ESM import so that we don't refer to any properties of the original object
	// Causing our generate step to think the image is used outside of the image optimization pipeline
	const clonedSrc = isESMImportedImage(resolvedOptions.src)
		? // @ts-expect-error - clone is a private, hidden prop
export type RemotePattern = {
	hostname?: string;
	pathname?: string;
	protocol?: string;
	port?: string;
};

/**
 * Evaluates whether a given URL matches the specified remote pattern based on protocol, hostname, port, and pathname.
 *
 * @param {URL} url - The URL object to be matched against the remote pattern.
 * @param {RemotePattern} remotePattern - The remote pattern object containing the protocol, hostname, port, and pathname to match.
 * @return {boolean} Returns `true` if the URL matches the given remote pattern; otherwise, `false`.
 */
export function matchPattern(url: URL, remotePattern: RemotePattern): boolean {
	return (
		matchProtocol(url, remotePattern.protocol) &&
		matchHostname(url, remotePattern.hostname, true) &&
		matchPort(url, remotePattern.port) &&
		matchPathname(url, remotePattern.pathname, true)
	);
}

/**
 * Checks if the given URL's port matches the specified port. If no port is provided, it returns `true`.
 *
 * @param {URL} url - The URL object whose port will be checked.
 * @param {string} [port=] - The port to match against the URL's port. Optional.
 * @return {boolean} Returns `true` if the URL's port matches the specified port or if no port is provided; otherwise, `false`.
 */
export function matchPort(url: URL, port?: string): boolean {
	return !port || port === url.port;
}

/**
 * Compares the protocol of the provided URL with a specified protocol.
 *
 * @param {URL} url - The URL object whose protocol needs to be checked.
 * @param {string} [protocol] - The protocol to compare against, without the trailing colon. If not provided, the method will always return `true`.
 * @return {boolean} Returns `true` if the protocol matches or if no protocol is specified; otherwise, `false`.
 */
export function matchProtocol(url: URL, protocol?: string): boolean {
	return !protocol || protocol === url.protocol.slice(0, -1);
}

/**
 * Matches a given URL's hostname against a specified hostname, with optional support for wildcard patterns.
 *
 * @param {URL} url - The URL object whose hostname is to be matched.
 * @param {string} [hostname] - The hostname to match against. Supports wildcard patterns if `allowWildcard` is `true`.
 * @param {boolean} [allowWildcard=false] - Indicates whether wildcard patterns in the `hostname` parameter are allowed.
 * @return {boolean} - Returns `true` if the URL's hostname matches the given hostname criteria; otherwise, `false`.
 */
export function matchHostname(url: URL, hostname?: string, allowWildcard = false): boolean {
	if (!hostname) {
		return true;
	} else if (!allowWildcard || !hostname.startsWith('*')) {
		return hostname === url.hostname;
	} else if (hostname.startsWith('**.')) {
		const slicedHostname = hostname.slice(2); // ** length
		return slicedHostname !== url.hostname && url.hostname.endsWith(slicedHostname);
	} else if (hostname.startsWith('*.')) {
		const slicedHostname = hostname.slice(1); // * length
		// Check if url hostname ends with the base domain
		if (!url.hostname.endsWith(slicedHostname)) {
			return false;
		}
		// Extract the subdomain part (before the base domain, excluding the dot)
		const subdomainWithDot = url.hostname.slice(0, -(slicedHostname.length - 1));
		// Should be exactly one subdomain part followed by a dot
		return subdomainWithDot.endsWith('.') && !subdomainWithDot.slice(0, -1).includes('.');
	}

	return false;
}

/**
 * Matches a given URL's pathname against a specified pattern, with optional support for wildcards.
 *
