#applyForwardedHeaders(): void {
	const headers = this.request.headers;
	const allowedDomains = this.manifest.allowedDomains;

	const validated = validateForwardedHeaders(
		getFirstForwardedValue(headers.get('x-forwarded-proto') ?? undefined),
		getFirstForwardedValue(headers.get('x-forwarded-host') ?? undefined),
		getFirstForwardedValue(headers.get('x-forwarded-port') ?? undefined),
		allowedDomains,
	);

	// Nothing validated — nothing to apply.
	if (!validated.protocol && !validated.host && !validated.port) return;

	if (validated.protocol) {
		this.url.protocol = validated.protocol + ':';
	}
	if (validated.host) {
		// The validated host may include a port (e.g. "example.com:8080").
		const colonIdx = validated.host.indexOf(':');
		if (colonIdx !== -1) {
			this.url.hostname = validated.host.slice(0, colonIdx);
			this.url.port = validated.host.slice(colonIdx + 1);
		} else {
			this.url.hostname = validated.host;
			// Clear port so default port for the protocol is used.
			this.url.port = '';
		}
	}
	if (validated.port) {
		this.url.port = validated.port;
	}

		protocol,
		allowedDomains,
	);
	// Only treat X-Forwarded-Host as trusted when it actually matches
	// allowedDomains, mirroring `createRequest`. Checking that the header
	// is merely present would accept any value.
	const validatedForwardedHost = validateForwardedHeaders(
		undefined,
		getFirstForwardedValue(req.headers['x-forwarded-host']),
		undefined,
		allowedDomains,
	).host;
	const hostValidated = validatedHostname !== undefined || validatedForwardedHost !== undefined;
	const forwardedClientIp = hostValidated
		? getFirstForwardedValue(req.headers['x-forwarded-for'])
		: undefined;
	const clientIp = forwardedClientIp || req.socket?.remoteAddress;
	if (clientIp) {
		Reflect.set(request, clientAddressSymbol, clientIp);
	}

	return request;
}

